using System.Collections.Generic;
using System.Collections.ObjectModel;

namespace Migs.ValueTypes.DataTypes
{
    public readonly record struct IMSIData
    {
        #region proeprties

        public string MCC { get; }
        public string MNC { get; }
        public string PLMN => $"{MCC}{MNC}";
        public string Region { get; }
        public string Country { get; }
        public string ISO { get; }
        public string Operator { get; }
        public string Brand { get; }
        public string TADIG { get; }
        public string Bands { get; }

        #endregion

        #region constructor

        public IMSIData()
        {
            MCC = "";
            MNC = "";
            Region = "";
            Country = "";
            ISO = "";
            Operator = "";
            Brand = "";
            TADIG = "";
            Bands = "";
        }

        public IMSIData(string mcc, string mnc, string region, string country, string iso, string @operator, string brand, string tadig, string bands)
        {
            MCC = mcc ?? "";
            MNC = mnc ?? "";
            Region = region ?? "";
            Country = country ?? "";
            ISO = iso ?? "";
            Operator = @operator ?? "";
            Brand = brand ?? "";
            TADIG = tadig ?? "";
            Bands = bands ?? "";
        }

        #endregion
    }

